      return paragraph(el, `#heading(level: ${tag[1]})[${body}]`);
    if (tag === "p") return paragraph(el, body);
    if (tag === "blockquote") return `#quote(block: true)[${body}]\n`;
    const marks: Record<string, string> = {
      strong: "strong",
      b: "strong",
      em: "emph",
      i: "emph",
      u: "underline",
      s: "strike",
      del: "strike",
      strike: "strike",
      sup: "super",
      sub: "sub",
