import type { TypstCompileRequest, TypstCompileResponse } from "./protocol";
export interface TypstCompileOptions { signal?: AbortSignal; onProgress?: (message:string)=>void; assets?: {path:string;url:string}[] }
type TypstExportOptions = TypstCompileOptions;
export interface TypstCompilation { pdf: Blob; pages: string[]; pageCount: number }

/** The renderer returns one SVG with independent page groups and shared glyph definitions. */
export function splitProofPages(svg?: string, sizes?: {width:number;height:number}[]): string[] {
  if (!svg || !sizes?.length) return [];
  const doc = new DOMParser().parseFromString(svg, "image/svg+xml");
  const root = doc.documentElement;
  const groups = Array.from(root.querySelectorAll(".typst-page"));
  let top = 0;
  return sizes.map((size,index) => {
    const page = root.cloneNode(true) as Element;
    const pageGroups = Array.from(page.querySelectorAll(".typst-page"));
    if (groups.length === sizes.length) {
      pageGroups.forEach((group,i) => { if(i !== index) group.remove(); else group.removeAttribute("transform"); });
      page.setAttribute("viewBox", `0 0 ${size.width} ${size.height}`);
    } else {
      page.setAttribute("viewBox", `0 ${top} ${size.width} ${size.height}`);
    }
    top += size.height;
    page.setAttribute("width", String(size.width)); page.setAttribute("height", String(size.height));
    page.setAttribute("xmlns", "http://www.w3.org/2000/svg");
    return page.outerHTML;
  });
}
'''
footer='''
/** A worker owns each snapshot: aborting it also stops synchronous WASM compilation. */
export async function compileTypstSource(source: string, options: TypstCompileOptions = {}): Promise<TypstCompilation> {
  const controller = new AbortController();
  const abort = () => controller.abort(options.signal?.reason);
  options.signal?.addEventListener("abort", abort, {once:true});
  if(options.signal?.aborted) abort();
  const timeout = setTimeout(() => controller.abort(new Error("Typesetting took too long. Try a smaller folio.")), 120_000);
  try {
    controller.signal.throwIfAborted();
    const assets = await loadAssets({source, assets:options.assets ?? []}, controller.signal);
    return await compileRequest({source, assets}, {...options, signal:controller.signal});
  } finally { clearTimeout(timeout); options.signal?.removeEventListener("abort", abort); }
}
