import { EditorState, Compartment } from "@codemirror/state";
import { EditorView, keymap, lineNumbers, highlightActiveLine, drawSelection } from "@codemirror/view";
import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
import { StreamLanguage, syntaxHighlighting, defaultHighlightStyle, bracketMatching } from "@codemirror/language";
import { searchKeymap, highlightSelectionMatches } from "@codemirror/search";

const typstLanguage = StreamLanguage.define<{ comment: boolean }>({
  startState: () => ({ comment: false }),
  token(stream, state) {
    if (state.comment) {
      if (stream.skipTo("*/")) { stream.match("*/"); state.comment = false; } else stream.skipToEnd();
      return "comment";
    }
    if (stream.match("//")) { stream.skipToEnd(); return "comment"; }
    if (stream.match("/*")) { state.comment = true; return "comment"; }
    if (stream.match(/"(?:[^"\\]|\\.)*"?/)) return "string";
    if (stream.sol() && stream.match(/=+\s/)) { stream.skipToEnd(); return "heading"; }
    if (stream.match(/#[a-zA-Z_][\w-]*/)) return "keyword";
    if (stream.match(/\b(?:true|false|none|auto|let|set|show|import|include)\b/)) return "keyword";
    if (stream.match(/\b\d+(?:\.\d+)?(?:pt|em|cm|mm|in|%)?/)) return "number";
    stream.next();
    return null;
  },
});

export function mountTypstCodeEditor(element: HTMLElement, source: string, options: { readOnly: boolean; onChange(source: string): void; onApply(): void }) {
  const readOnly = new Compartment();
  let settingValue = false;
  const view = new EditorView({
    parent: element,
    state: EditorState.create({
      doc: source,
      extensions: [
        lineNumbers(), history(), drawSelection(), highlightActiveLine(), bracketMatching(), highlightSelectionMatches(), typstLanguage,
        syntaxHighlighting(defaultHighlightStyle), EditorView.lineWrapping,
        EditorView.contentAttributes.of({ "aria-label": "Typst source", spellcheck: "false" }),
        readOnly.of(EditorState.readOnly.of(options.readOnly)),
        keymap.of([{ key: "Mod-Enter", run: () => { options.onApply(); return true; } }, ...defaultKeymap, ...historyKeymap, ...searchKeymap, indentWithTab]),
        EditorView.updateListener.of((update) => { if (update.docChanged && !settingValue) options.onChange(update.state.doc.toString()); }),
        EditorView.theme({
          "&": { height: "100%", backgroundColor: "var(--color-paper)", color: "var(--color-ink)", fontSize: "13px" },
          ".cm-scroller": { overflow: "auto", fontFamily: "var(--font-typewriter, monospace)", lineHeight: "1.65" },
          ".cm-content": { padding: "1rem 0" },
          ".cm-line": { padding: "0 1rem" },
          ".cm-gutters": { backgroundColor: "var(--color-paper-soft)", color: "var(--color-ink-light)", borderColor: "var(--color-paper-3)" },
          ".cm-activeLine, .cm-activeLineGutter": { backgroundColor: "var(--color-paper-soft)" },
          ".cm-cursor": { borderLeftColor: "var(--color-ink)" },
          "&.cm-focused": { outline: "2px solid var(--color-cobalt)", outlineOffset: "-2px" },
        }),
      ],
    }),
  });
  return {
    setSource(next: string) {
      if (view.state.doc.toString() === next) return;
      settingValue = true;
      try { view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: next } }); } finally { settingValue = false; }
    },
    setReadOnly(value: boolean) { view.dispatch({ effects: readOnly.reconfigure(EditorState.readOnly.of(value)) }); },
    focus() { view.focus(); },
    destroy() { view.destroy(); },
  };
}
import type { Editor } from "@tiptap/core";
import type { ExportPayload } from "../exchange";
import {
  FOLIO_CONTENT_SAVED,
  loadFolioContentSnapshotFromIdb,
  saveFolioTypstToIdb,
  type FolioContentSnapshot,
} from "../idb";
import { htmlToTypst, typstToHtml, reconcileTypstSource } from "./document";
import { compileTypstSource, type TypstCompilation } from "./client";
import {
  loadTypstSourceDraft,
  saveTypstSourceDraft,
  clearTypstSourceDraft,
} from "./source-drafts";

export interface TypstSessionState {
  source: string;
  dirty: boolean;
  conflict: boolean;
  status: string;
  error: string;
  pages: string[];
  pdfUrl: string;
  applying: boolean;
}
export interface TypstSession {
  changeSource(source: string): void;
  apply(): Promise<void>;
  discard(): Promise<void>;
  refreshProof(): void;
  destroy(): void;
}
export interface TypstSessionOptions {
  editor: Editor;
  folioId: string;
  readOnly: boolean;
  onState(state: TypstSessionState): void;
  getPayload(source: string): Promise<ExportPayload>;
  onPages(pageCount: number): void;
}

/** One folio owns its source draft, compiler cancellation and proof object URLs. */
export async function createTypstSession(
  options: TypstSessionOptions,
): Promise<TypstSession> {
  const { editor, folioId } = options;
  let destroyed = false;
  let applying = false;
  let replacing = false;
  let revision = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let controller: AbortController | undefined;
  let proofSource: string | undefined;
  let proof: TypstCompilation | undefined;
  let baselineHtml = editor.getHTML();
  const visualHistory = new Set([baselineHtml]);
  const snapshot = await loadFolioContentSnapshotFromIdb(folioId);
  let baseSource = snapshot?.typstSource;
  let cleanSource =
    baseSource !== undefined
      ? reconcileTypstSource(baseSource, baselineHtml)
      : htmlToTypst(baselineHtml);
  const recovered = await loadTypstSourceDraft(folioId);
  const state: TypstSessionState = {
    source: recovered?.source ?? cleanSource,
    dirty: Boolean(recovered && recovered.source !== cleanSource),
    conflict: Boolean(
      recovered && recovered.baseSource !== (baseSource ?? cleanSource),
    ),
    status: recovered ? "Recovered source draft" : "Preparing proof…",
    error: "",
    pages: [],
    pdfUrl: "",
    applying: false,
  };
  if (recovered) baseSource = recovered.baseSource;
  function emit() {
    if (destroyed) return;
    state.applying = applying;
    editor.setEditable(!options.readOnly && !state.dirty && !applying);
    options.onState({ ...state, pages: [...state.pages] });
  }
  function sourceEvent() {
    window.dispatchEvent(
      new CustomEvent("twyne:typst-source-state", {
        detail: { folioId, source: state.source, pending: state.dirty },
      }),
    );
  }
  function draft() {
    if (destroyed || options.readOnly) return;
    void saveTypstSourceDraft({
      folioId,
      source: state.source,
      baseSource: baseSource ?? cleanSource,
      updatedAt: Date.now(),
    }).catch((error) => {
      if (destroyed) return;
      state.error =
        error instanceof Error
          ? error.message
          : "Source could not be saved on this device.";
      emit();
    });
  }
  function cancel() {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
    controller?.abort();
    controller = undefined;
    revision++;
  }
  function releaseProof() {
    state.pages.forEach((url) => URL.revokeObjectURL(url));
    if (state.pdfUrl) URL.revokeObjectURL(state.pdfUrl);
  }
  async function compile(): Promise<TypstCompilation | undefined> {
    cancel();
    const currentRevision = revision;
    const source = state.source;
    const task = new AbortController();
    controller = task;
    state.status = "Typesetting…";
    state.error = "";
    emit();
    try {
      const payload = await options.getPayload(source);
      task.signal.throwIfAborted();
      const compiled = await compileTypstSource(source, {
        payload,
        signal: task.signal,
        onProgress: (status) => {
          if (!destroyed && currentRevision === revision) {
            state.status = status;
            emit();
          }
        },
      });
      if (destroyed || currentRevision !== revision || source !== state.source)
        return undefined;
      const urls = compiled.pages.map((svg) =>
        URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" })),
      );
      const pdfUrl = URL.createObjectURL(compiled.pdf);
      releaseProof();
      state.pages = urls;
      state.pdfUrl = pdfUrl;
